import React, { useState, useEffect } from 'react';
import { Droplets, Check, X, AlertTriangle, Calendar, Clock, Milk } from 'lucide-react';
import { milkService, healthService } from '../../services/api';
import toast from 'react-hot-toast';

/**
 * Hızlı Sağım Matrisi (Rapid Parlor Milk Entry Grid)
 * Sağımhanede tüm sağmalların sabah/öğle/akşam litrelerini tek ekranda topluca girmeyi sağlar.
 * Antibiyotikli / arınma süresindeki hayvanları kırmızı bayrakla uyararak tank sütünün bozulmasını önler.
 */
export default function RapidMilkingModal({ isOpen, onClose, animals = [], farmId, onSaved }) {
  const [recordDate, setRecordDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [session, setSession] = useState('Sabah'); // Sabah, Öğle, Akşam
  const [quantities, setQuantities] = useState({});
  const [saving, setSaving] = useState(false);
  const [treatedAnimalIds, setTreatedAnimalIds] = useState(new Set());

  useEffect(() => {
    if (!isOpen) return;
    let isMounted = true;
    const fetchTreatedAnimals = async () => {
      try {
        const res = await healthService.list(farmId, { limit: 100 });
        const records = res.data?.records || res.data?.data || res.data || [];
        const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
        
        const activeIds = new Set();
        records.forEach(r => {
          if (['medication', 'vaccination'].includes(r.record_type)) {
            const rDate = new Date(r.record_date);
            if (rDate >= sevenDaysAgo) {
              activeIds.add(r.animal_id);
            }
          }
        });
        if (isMounted) setTreatedAnimalIds(activeIds);
      } catch (_) {}
    };
    fetchTreatedAnimals();
    return () => { isMounted = false; };
  }, [isOpen, farmId]);

  if (!isOpen) return null;

  const femaleAnimals = animals.filter(a => a.gender === 'F');

  const handleQtyChange = (animalId, val) => {
    setQuantities(prev => ({
      ...prev,
      [animalId]: val
    }));
  };

  const handleSaveAll = async () => {
    const entries = Object.entries(quantities)
      .map(([animalId, qtyStr]) => {
        const qty = parseFloat(String(qtyStr).replace(',', '.'));
        return { animalId: parseInt(animalId, 10), quantity: qty };
      })
      .filter(item => !isNaN(item.quantity) && item.quantity > 0);

    if (entries.length === 0) {
      toast.error('Lütfen en az bir hayvan için süt miktarı girin.');
      return;
    }

    const hasTreatedMilking = entries.some(e => treatedAnimalIds.has(e.animalId));

    setSaving(true);
    let successCount = 0;
    let failCount = 0;

    try {
      await Promise.all(
        entries.map(async (entry) => {
          try {
            await milkService.create(farmId, {
              animal_id: entry.animalId,
              record_date: recordDate,
              record_time: session,
              quantity: entry.quantity,
              notes: treatedAnimalIds.has(entry.animalId) ? '[ARINMA SÜRESİ] İlaçlı süt - tanka dökülmemelidir' : 'Toplu sağım girişi'
            });
            successCount++;
          } catch {
            failCount++;
          }
        })
      );

      if (successCount > 0) {
        if (hasTreatedMilking) {
          toast((t) => (
            <span className="text-xs font-bold text-red-800">
              ⚠️ DİKKAT: İlaç tedavisi gören hayvan(lar) sağıldı! Sütleri tanka dökülmemeli, imha edilmeli veya yavruya ayrılmalıdır.
            </span>
          ), { duration: 6000, icon: '🛑' });
        }
        toast.success(`${successCount} hayvanın sağım kaydı kaydedildi.${failCount > 0 ? ` (${failCount} hatalı)` : ''}`);
        if (onSaved) onSaved();
        onClose();
      } else {
        toast.error('Kayıtlar işlenirken hata oluştu.');
      }
    } catch {
      toast.error('Toplu sağım sırasında hata oluştu.');
    } finally {
      setSaving(false);
    }
  };

  const totalLitres = Object.values(quantities).reduce((acc, curr) => {
    const n = parseFloat(String(curr).replace(',', '.'));
    return acc + (isNaN(n) ? 0 : n);
  }, 0);

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md z-50 flex items-center justify-center p-3 sm:p-4 animate-fade-in">
      <div className="bg-white rounded-3xl shadow-2xl border border-slate-100 w-full max-w-2xl max-h-[92vh] flex flex-col overflow-hidden">
        {/* Executive Header */}
        <div
          className="p-5 text-white flex items-center justify-between relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #091e3a 0%, #1e3a8a 55%, #0f172a 100%)' }}
        >
          <div className="absolute top-0 right-0 w-48 h-48 bg-sky-500/10 rounded-full blur-2xl pointer-events-none" />
          <div className="flex items-center gap-3 relative z-10">
            <div className="w-11 h-11 rounded-2xl bg-white/10 backdrop-blur-md border border-white/20 flex items-center justify-center shadow-inner">
              <Droplets className="w-5 h-5 text-sky-300" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-white text-base">Hızlı Sağımhane Matrisi</h3>
                <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black uppercase tracking-wider bg-sky-500/20 text-sky-200 border border-sky-400/30">
                  <Milk className="w-3 h-3 text-sky-300" /> Toplu Giriş
                </span>
              </div>
              <p className="text-xs text-sky-200/80 mt-0.5">Tüm sağmalların sağım verilerini tek ekrandan hızlıca kaydedin</p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 border border-white/15 text-white/80 hover:text-white flex items-center justify-center transition-all cursor-pointer relative z-10"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Ayarlar Çubuğu */}
        <div className="p-3.5 sm:p-4 bg-slate-50 border-b border-slate-100 flex flex-wrap items-center justify-between gap-3 text-xs">
          <div className="flex items-center gap-2">
            <Calendar className="w-4 h-4 text-slate-400" />
            <span className="font-bold text-slate-600">Tarih:</span>
            <input
              type="date"
              value={recordDate}
              onChange={e => setRecordDate(e.target.value)}
              className="px-3 py-1.5 rounded-xl border border-slate-200 bg-white font-semibold text-slate-800 shadow-2xs focus:border-sky-500 focus:outline-none"
            />
          </div>

          <div className="flex items-center gap-1.5">
            <Clock className="w-4 h-4 text-slate-400 mr-1" />
            <span className="font-bold text-slate-600 mr-1">Vakit:</span>
            {['Sabah', 'Öğle', 'Akşam'].map(s => (
              <button
                key={s}
                type="button"
                onClick={() => setSession(s)}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all ${
                  session === s
                    ? 'bg-sky-600 text-white shadow-sm ring-2 ring-sky-600/30'
                    : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-100'
                }`}
              >
                {s}
              </button>
            ))}
          </div>

          <div className="bg-sky-50 border border-sky-200/70 rounded-xl px-3 py-1.5 flex items-center gap-2">
            <span className="text-slate-500 font-semibold text-[11px]">Sağılan Toplam:</span>
            <strong className="text-sky-700 text-sm font-black">{totalLitres.toFixed(1)} L</strong>
          </div>
        </div>

        {/* Hayvan Tablosu */}
        <div className="flex-1 overflow-y-auto p-4 max-h-[50vh] divide-y divide-slate-100 [scrollbar-width:thin]">
          {femaleAnimals.length === 0 ? (
            <div className="text-center py-12 text-slate-400 text-xs">
              Kayıtlı sağmal dişi hayvan bulunamadı.
            </div>
          ) : (
            femaleAnimals.map(a => {
              const isTreated = treatedAnimalIds.has(a.id);
              const val = quantities[a.id] || '';
              return (
                <div
                  key={a.id}
                  className={`py-3 px-3 flex items-center justify-between gap-3 rounded-2xl transition-all ${
                    isTreated
                      ? 'bg-rose-50/80 border border-rose-200 my-1'
                      : val
                      ? 'bg-sky-50/50 hover:bg-sky-50/80'
                      : 'hover:bg-slate-50'
                  }`}
                >
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                      <p className="font-bold text-sm text-slate-800 truncate">{a.name}</p>
                      {isTreated && (
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-600 text-white shadow-xs animate-pulse">
                          <AlertTriangle className="w-3 h-3" /> Arınma Süresinde
                        </span>
                      )}
                    </div>
                    <p className="text-[11px] text-slate-400 font-mono mt-0.5">
                      {a.code} • {a.breed || a.species}
                      {isTreated && <span className="text-rose-700 font-bold ml-2">🛑 Antibiyotikli / Tanka Karıştırmayın</span>}
                    </p>
                  </div>

                  <div className="flex items-center gap-2">
                    <div className="relative">
                      <input
                        type="number"
                        step="0.1"
                        min="0"
                        placeholder="0.0"
                        value={quantities[a.id] || ''}
                        onChange={e => handleQtyChange(a.id, e.target.value)}
                        className={`w-24 text-right pr-7 pl-3 py-2 rounded-xl border text-sm font-black focus:outline-none transition ${
                          isTreated
                            ? 'border-rose-400 text-rose-900 bg-white focus:ring-2 focus:ring-rose-400'
                            : 'border-slate-200 text-slate-900 bg-white focus:border-sky-500 focus:ring-2 focus:ring-sky-500/20'
                        }`}
                      />
                      <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400 pointer-events-none">L</span>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Alt Kısım ve Kaydet */}
        <div className="p-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
          <span className="text-xs text-slate-500 font-medium">
            <span className="font-bold text-slate-700">{Object.keys(quantities).length}</span> hayvana süt girildi
          </span>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2.5 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-xl hover:bg-slate-100 transition shadow-xs"
            >
              Vazgeç
            </button>
            <button
              type="button"
              disabled={saving}
              onClick={handleSaveAll}
              className="px-5 py-2.5 text-xs font-bold text-white rounded-xl shadow-md transition flex items-center gap-2 hover:brightness-110 disabled:opacity-50"
              style={{ background: 'linear-gradient(135deg, #0284c7 0%, #0369a1 100%)' }}
            >
              {saving ? 'Kaydediliyor...' : <><Check className="w-4 h-4" /> Tümünü Kaydet</>}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
