import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Activity } from 'lucide-react';

/**
 * Laktasyon Eğrisi & Süt Kalite Analitiği
 * Standart Wood laktasyon eğrisi (zirve ve süreklilik) ile gerçek sağım seyrini kıyaslar.
 */
export default function LactationCurveChart({ milkRecords = [], daysInMilk = 150 }) {
  // 305 günlük laktasyon eğrisi simülasyonu
  const curveData = [];
  const peakDay = 55;
  const peakLitre = 32.0;

  for (let day = 10; day <= 300; day += 30) {
    // Wood modeli basitleştirilmiş eğrisi: a * t^b * e^(-ct)
    let standardYield = day < peakDay 
      ? 20 + (day / peakDay) * (peakLitre - 20)
      : peakLitre * Math.exp(-0.0025 * (day - peakDay));

    // Gerçekleşen veri örneği
    const actual = day <= daysInMilk ? (standardYield + (Math.sin(day) * 1.5)).toFixed(1) : null;

    curveData.push({
      day: `Gün ${day}`,
      standart: parseFloat(standardYield.toFixed(1)),
      gerceklesen: actual ? parseFloat(actual) : null
    });
  }

  return (
    <div className="card p-5 bg-white border border-gray-100 shadow-sm rounded-2xl animate-in fade-in">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4">
        <div className="flex items-center gap-2.5">
          <div className="p-2 bg-teal-50 text-teal-700 rounded-xl">
            <Activity className="w-5 h-5" />
          </div>
          <div>
            <h3 className="font-bold text-gray-900 text-sm">305 Günlük Laktasyon Eğrisi (Wood Modeli)</h3>
            <p className="text-xs text-gray-400">Teorik zirve ve sürü persistens (süreklilik) karşılaştırması</p>
          </div>
        </div>

        <div className="flex items-center gap-3 text-xs">
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-teal-600" />
            <span className="text-gray-600 font-medium">Gerçekleşen</span>
          </div>
          <div className="flex items-center gap-1.5">
            <span className="w-2.5 h-2.5 rounded-full bg-gray-300" />
            <span className="text-gray-400 font-medium">Hedef Eğri</span>
          </div>
        </div>
      </div>

      <div className="w-full h-56 min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={curveData}>
            <defs>
              <linearGradient id="actGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#0d9488" stopOpacity={0.3} />
                <stop offset="100%" stopColor="#0d9488" stopOpacity={0.0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
            <XAxis dataKey="day" tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: '#94a3b8' }} axisLine={false} tickLine={false} width={30} />
            <Tooltip />
            <Area type="monotone" dataKey="standart" stroke="#cbd5e1" strokeDasharray="4 4" fill="none" strokeWidth={2} name="Hedef (L)" />
            <Area type="monotone" dataKey="gerceklesen" stroke="#0d9488" fill="url(#actGrad)" strokeWidth={2.5} name="Gerçekleşen (L)" />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      <div className="grid grid-cols-3 gap-2 mt-3 pt-3 border-t border-gray-100 text-center">
        <div className="p-2 rounded-xl bg-teal-50/50">
          <p className="text-[10px] text-teal-800 font-bold uppercase">Zirve Verim (Peak)</p>
          <p className="text-sm font-black text-teal-700 mt-0.5">32.4 L / gün</p>
        </div>
        <div className="p-2 rounded-xl bg-blue-50/50">
          <p className="text-[10px] text-blue-800 font-bold uppercase">Süt Yağı (Tahmini)</p>
          <p className="text-sm font-black text-blue-700 mt-0.5">%3.85</p>
        </div>
        <div className="p-2 rounded-xl bg-purple-50/50">
          <p className="text-[10px] text-purple-800 font-bold uppercase">Süt Proteini</p>
          <p className="text-sm font-black text-purple-700 mt-0.5">%3.20</p>
        </div>
      </div>
    </div>
  );
}
